export function diffLines(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) throw new TypeError('both sides must be arrays');
  for (const line of a) {
    if (typeof line !== 'string') throw new TypeError('every line must be a string');
  }
  for (const line of b) {
    if (typeof line !== 'string') throw new TypeError('every line must be a string');
  }

  const n = a.length;
  const m = b.length;
  const width = m + 1;
  // lcs[i * width + j] is the length of the longest common subsequence of
  // a.slice(i) and b.slice(j). The table is filled from the end backwards.
  const lcs = new Int32Array((n + 1) * width);
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      lcs[i * width + j] = a[i] === b[j]
        ? lcs[(i + 1) * width + j + 1] + 1
        : Math.max(lcs[(i + 1) * width + j], lcs[i * width + j + 1]);
    }
  }

  const script = [];
  let i = 0;
  let j = 0;
  while (i < n || j < m) {
    if (i >= n) {
      script.push({ op: 'add', line: b[j] });
      j += 1;
      continue;
    }
    if (j >= m) {
      script.push({ op: 'remove', line: a[i] });
      i += 1;
      continue;
    }
    if (a[i] === b[j]) {
      script.push({ op: 'keep', line: a[i] });
      i += 1;
      j += 1;
      continue;
    }
    if (lcs[(i + 1) * width + j] > lcs[i * width + j + 1]) {
      script.push({ op: 'remove', line: a[i] });
      i += 1;
      continue;
    }
    script.push({ op: 'add', line: b[j] });
    j += 1;
  }
  return script;
}
